// Runs whenever a LendLoop workflow execution fails (after node retries are exhausted).
// Logs only metadata: no payloads, so no personal data ends up in logs.
const e = $input.first().json;
const record = {
  alert: 'lendloop_workflow_failed',
  workflow: e.workflow?.name,
  workflowId: e.workflow?.id,
  executionId: e.execution?.id ?? null,
  executionUrl: e.execution?.url ?? null,
  failedNode: e.execution?.lastNodeExecuted ?? e.trigger?.error?.node?.name ?? null,
  message: e.execution?.error?.message ?? e.trigger?.error?.message ?? 'unknown error',
  at: new Date().toISOString(),
};
console.error('[lendloop] WORKFLOW FAILED', JSON.stringify(record));
// Production: add an Email / Slack / PagerDuty node after this one.
return [{ json: record }];
